CREATE OR REPLACE TABLE field_parcel_pairs AS
SELECT f.Id AS field_id, p.cod_imovel,
       ST_Area(ST_Intersection(f.geom, p.geom)) AS inter_area,
       ST_Area(f.geom) AS field_area
FROM fields_in_envelope f
JOIN listed_parcels_geom p ON ST_Intersects(f.geom, p.geom)
WHERE ST_Area(ST_Intersection(f.geom, p.geom)) > 0;
SELECT count(*) FROM field_parcel_pairs;
SELECT count(DISTINCT field_id) FROM field_parcel_pairs;
"

cd /workspace
duckdb db/analysis.duckdb -csv -c "
LOAD spatial;
SET geometry_always_xy=true;
CREATE OR REPLACE TABLE field_single AS
SELECT field_id, field_area,
  max(inter_area/field_area) AS max_single_frac
FROM field_parcel_pairs
GROUP BY field_id, field_area;

CREATE OR REPLACE TABLE field_primary AS
SELECT fs.field_id,
  (SELECT p.cod_imovel FROM field_parcel_pairs p
   WHERE p.field_id = fs.field_id AND (p.inter_area/p.field_area) >= fs.max_single_frac - 1e-9
   ORDER BY p.cod_imovel ASC LIMIT 1) AS primary_cod_imovel
FROM field_single fs;

SELECT count(*) FROM field_single;
SELECT * FROM field_single ORDER BY field_id LIMIT 5;
"

