  COALESCE(SUM(ST_Area(ST_Intersection(f.geom, u.geom))),0) / ST_Area(f.geom) AS agg_frac
FROM fields_in_envelope f
LEFT JOIN listed_union_buffered u ON ST_Intersects(f.geom, u.geom)
GROUP BY f.Id, f.geom;
SELECT count(*) FROM field_aggregate;
"

